import{_ as e,o as t,c as s,ag as l}from"./chunks/framework.1IVNT0ce.js";const m=JSON.parse('{"title":"Example: AI Chat-Style CLI","description":"","frontmatter":{},"headers":[],"relativePath":"examples/gemini-style-cli.md","filePath":"examples/gemini-style-cli.md"}'),o={name:"examples/gemini-style-cli.md"};function n(i,a,r,p,c,h){return t(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="example-ai-chat-style-cli" tabindex="-1">Example: AI Chat-Style CLI <a class="header-anchor" href="#example-ai-chat-style-cli" aria-label="Permalink to &quot;Example: AI Chat-Style CLI&quot;">​</a></h1><p>The repository includes a chat-style demo at <code>examples/chat_ai.py</code>. It is the closest example to an AI assistant interface built with Klix primitives.</p><p>This page uses “Gemini-style” as a UX description, not as a model integration. The example is a local demo UI with fake assistant logic. It does not call external APIs.</p><h2 id="what-this-example-demonstrates" tabindex="-1">What This Example Demonstrates <a class="header-anchor" href="#what-this-example-demonstrates" aria-label="Permalink to &quot;What This Example Demonstrates&quot;">​</a></h2><p>The chat demo shows how to build a more conversational terminal experience with:</p><ul><li>normal text input as messages</li><li>slash commands for control actions</li><li>streamed assistant output</li><li>a lightweight layout with header and status</li><li>a custom loop built on Klix internals</li></ul><p>That last point matters. The standard <code>App.run()</code> loop is command-oriented. This example shows how to bend the framework toward free-form chat while still using the same session, UI, middleware, and renderer layers.</p><h2 id="why-a-custom-loop-is-needed" tabindex="-1">Why A Custom Loop Is Needed <a class="header-anchor" href="#why-a-custom-loop-is-needed" aria-label="Permalink to &quot;Why A Custom Loop Is Needed&quot;">​</a></h2><p>The default app loop assumes slash commands are what should be parsed and routed. For a chat app, you usually want:</p><ul><li>plain text to become a message</li><li>slash commands to remain available for actions like <code>/help</code> and <code>/clear</code></li></ul><p><code>examples/chat_ai.py</code> handles that by:</p><ol><li>creating a session manually</li><li>using the same <code>KlixCompleter</code>, renderer, input engine, and UI namespace as <code>App</code></li><li>routing slash commands through the router and middleware</li><li>treating non-command input as chat text</li></ol><p>This is a good example of Klix as a framework rather than just a prebuilt loop.</p><h2 id="streaming-output" tabindex="-1">Streaming Output <a class="header-anchor" href="#streaming-output" aria-label="Permalink to &quot;Streaming Output&quot;">​</a></h2><p>One of the most useful patterns in the example is streamed assistant text:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">layout</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">main</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">print</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Assistant: </span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">info</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> bold</span><span style="color:#89DDFF;">=True,</span><span style="color:#BABED8;font-style:italic;"> end</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">await</span><span style="color:#BABED8;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">stream</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">chunks</span><span style="color:#89DDFF;">(),</span><span style="color:#BABED8;font-style:italic;"> color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">text</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> end</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#BABED8;">\\n\\n</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span></code></pre></div><p>This creates the feeling of live generation without building a real model backend.</p><p>See <a href="./../guides/creating-ui">Creating UI</a> for the general streaming pattern.</p><h2 id="layout-pattern" tabindex="-1">Layout Pattern <a class="header-anchor" href="#layout-pattern" aria-label="Permalink to &quot;Layout Pattern&quot;">​</a></h2><p>The example uses Klix layout in the intended way:</p><ul><li>header for app identity</li><li>status line for model/theme/detail</li><li>main transcript for conversation history</li></ul><p>It avoids trying to make the whole transcript a retained widget tree, which fits the current layout engine well.</p><h2 id="fake-assistant-logic" tabindex="-1">Fake Assistant Logic <a class="header-anchor" href="#fake-assistant-logic" aria-label="Permalink to &quot;Fake Assistant Logic&quot;">​</a></h2><p>The assistant behavior is intentionally simple:</p><ul><li>canned intelligent-looking phrasing</li><li>question detection</li><li>string transformations</li><li>light topic-specific branching</li></ul><p>That keeps the example focused on UX and flow rather than network integration.</p><h2 id="commands-in-a-chat-app" tabindex="-1">Commands In A Chat App <a class="header-anchor" href="#commands-in-a-chat-app" aria-label="Permalink to &quot;Commands In A Chat App&quot;">​</a></h2><p>The demo keeps a few slash commands:</p><ul><li><code>/help</code></li><li><code>/clear</code></li><li><code>/theme</code></li><li><code>/exit</code></li></ul><p>This is a useful pattern for conversational CLIs in general. Plain text handles the primary experience; slash commands handle control and utility behavior.</p><h2 id="what-to-learn-from-this-example" tabindex="-1">What To Learn From This Example <a class="header-anchor" href="#what-to-learn-from-this-example" aria-label="Permalink to &quot;What To Learn From This Example&quot;">​</a></h2><ul><li>You can use Klix without <code>app.run()</code> when the interaction model demands it.</li><li>The session and UI objects are reusable outside the default loop.</li><li>Middleware still adds value in custom flows.</li><li>Streaming and layout are enough to make a terminal app feel polished.</li></ul><h2 id="common-pitfalls" tabindex="-1">Common Pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common Pitfalls&quot;">​</a></h2><ul><li>Assuming the default app loop can be used unchanged for free-form chat.</li><li>Building a chat transcript entirely in layout state instead of printing to the main region.</li><li>Forgetting that command parsing is still slash-based even inside a custom loop.</li></ul><h2 id="related-reading" tabindex="-1">Related Reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related Reading&quot;">​</a></h2><ul><li><a href="./../concepts/architecture">Architecture</a></li><li><a href="./../concepts/input-engine">Input Engine</a></li><li><a href="./../concepts/ui">UI</a></li></ul>`,36)])])}const u=e(o,[["render",n]]);export{m as __pageData,u as default};
